// 1) Wrapper aus dem HTTP-Node holen
const wrapper = $json;         // z.B. { data: "...string..." }
let response = wrapper.data;   // das ist aktuell ein String

// 2) Falls das innere 'data' ein String ist: parsen
if (typeof response === 'string') {
  try {
    response = JSON.parse(response);
  } catch (error) {
    // JSON fehlerhaft -> Debug als EIN Item zurückgeben
    return [
      {
        json: {
          found: false,
          parseError: true,
          errorMessage: String(error),
          rawWrapper: wrapper,
        },
      },
    ];
  }
}

// 3) Jetzt ist 'response' das eigentliche Klaviyo-Objekt:
//    { data: [ { type: 'profile', id: '...', attributes: {...} }, ... ], links: {...} }

const profiles = Array.isArray(response.data) ? response.data : [];

if (profiles.length === 0) {
  return [
    {
      json: {
        found: false,
        message: 'Keine Profile gefunden oder unerwartetes Format',
        rawResponse: response,
      },
    },
  ];
}

// 4) Über ALLE Profile iterieren und jeweils ein Item bauen
const items = profiles.map(profile => {
  const attrs = profile.attributes || {};
  const location = attrs.location || {};
  const props = attrs.properties || {};

  return {
    json: {
      found: true,

      profileId: profile.id,
      email: attrs.email,
      phone: attrs.phone_number,
      firstName: attrs.first_name,
      lastName: attrs.last_name,

      city: location.city,
      zip: location.zip,
      country: location.country,
      timezone: location.timezone,

      preferences: props.preference,
      acceptsMarketing: props['Accepts Marketing'],
    },
  };
});

// 5) n8n erwartet ein Array von Items
return items;

