// Eingehende Items haben:
// item.json.user_email
// item.json.aktive_abos (String, z.B. "Liebesbüchse Buch, Zauberbüchse Buch")

return items.map(item => {
  const email = item.json.user_email;
  const aktiveAbosRaw = item.json.aktive_abos || '';

  // Für robustere Suche alles in Kleinbuchstaben
  const aktiveAbos = aktiveAbosRaw.toLowerCase();

  const zauberbuechse =
    aktiveAbos.includes('zauberbüchse') || aktiveAbos.includes('zauberbuechse');
  const dunkelbuechse =
    aktiveAbos.includes('dunkelbüchse') || aktiveAbos.includes('dunkelbuechse');
  const liebesbuechse =
    aktiveAbos.includes('liebesbüchse') || aktiveAbos.includes('liebesbuechse');

  return {
    json: {
      email,
      zauberbuechse,
      dunkelbuechse,
      liebesbuechse,
    },
  };
});

// 0) Abo-Boolean-Werte aus dem Node "Wandle DB Output um" holen
// n8n matched den Item-Index automatisch, d.h. du bekommst hier
// die Werte des entsprechenden Items.
const aboSource = $node['Wandelt DB Output um'].json || {};

const zauberbuechse  = Boolean(aboSource.zauberbuechse);
const dunkelbuechse  = Boolean(aboSource.dunkelbuechse);
const liebesbuechse  = Boolean(aboSource.liebesbuechse);

// 1) Wrapper aus dem HTTP-Node holen
const wrapper = $json;          // z.B. { data: "...string..." }
let response = wrapper.data;    // das ist aktuell ein String

// Helper, um die E-Mail aus links.self zu holen (wenn nötig)
function extractEmailFromSelfLink(selfLink) {
  if (!selfLink) return undefined;
  try {
    const decoded = decodeURIComponent(selfLink);
    // Erwartetes Muster: ...?filter=equals(email,"EMAIL")
    const match = decoded.match(/filter=equals\(email,"([^"]+)"\)/);
    return match ? match[1] : undefined;
  } catch (e) {
    return undefined;
  }
}

// 2) Falls das innere 'data' ein String ist: parsen
if (typeof response === 'string') {
  try {
    response = JSON.parse(response);
  } catch (error) {
    const selfLink = wrapper.links?.self;
    const emailFromSelf = extractEmailFromSelfLink(selfLink);

    return {
      json: {
        found: false,
        parseError: true,
        errorMessage: String(error),
        email: emailFromSelf,
        zauberbuechse,
        dunkelbuechse,
        liebesbuechse,
        rawWrapper: wrapper,
      },
    };
  }
}

// 3) Jetzt ist 'response' das eigentliche Klaviyo-Objekt:
//    { data: [ { type: 'profile', id: '...', attributes: {...} } ], links: {...} }

const profiles = Array.isArray(response?.data) ? response.data : [];
const profile = profiles[0]; // 0 oder undefined

let attrs = profile?.attributes || {};
let email = attrs.email;

// Falls kein Profil oder keine E-Mail im Profil, Email aus links.self rekonstruieren
if (!email && response?.links?.self) {
  email = extractEmailFromSelfLink(response.links.self);
}

// 4) Wenn kein Profil gefunden wurde, trotzdem E-Mail + Abos zurückgeben
if (!profile || typeof profile !== 'object') {
  return {
    json: {
      found: false,
      email,
      zauberbuechse,
      dunkelbuechse,
      liebesbuechse,
      message: 'Kein Profil gefunden oder leeres data[]',
      rawResponse: response,
    },
  };
}

// 5) Profil vorhanden -> normale "erfolgreiche" Struktur inkl. Abo-Booleans
return {
  json: {
    found: true,
    profileId: profile.id,
    email,
    zauberbuechse,
    dunkelbuechse,
    liebesbuechse,
    // Optional: falls du mehr brauchst
    // attributes: attrs,
  },
};

const kzauberbuechse = $json.zauberbuechse;
const kliebesbuechse = $json.liebesbuechse;
const kdunkelbuechse = $json.dunkelbuechse;

const kid = $json.profileId;

return {
  json: {
    data: {
      type: 'profile',
      id: kid,
      attributes: {
        properties: {
          zauberbuechse: kzauberbuechse,
          dunkelbuechse: kdunkelbuechse,
          liebesbuechse: kliebesbuechse,
        },
      },
    },
  },
};

const kemail = $json.email;
const kzauberbuechse = $json.zauberbuechse;
const kliebesbuechse = $json.liebesbuechse;
const kdunkelbuechse = $json.dunkelbuechse;


return {
  json: {
    data: {
      type: 'profile',
      attributes: {
        email: kemail,
        properties: {
          zauberbuechse: kzauberbuechse,
          dunkelbuechse: kdunkelbuechse,
          liebesbuechse: kliebesbuechse,
        },
      },
    },
  },
};

// items = eingehende Items
// Jedes Item hat unter item.json.data einen JSON-String (Klaviyo-Response)

let countZauber = 0;
let countDunkel = 0;
let countLiebe = 0;

let createdProfiles = 0;
let updatedProfiles = 0;
let profilesWithoutTimestamps = 0;

for (const item of items) {
  const raw = item.json.data;

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    // kaputtes JSON -> überspringen
    continue;
  }

  const attrs = parsed?.data?.attributes || {};
  const props = attrs.properties || {};

  // Abo-Flags zählen
  if (props.zauberbuechse === true) {
    countZauber++;
  }
  if (props.dunkelbuechse === true) {
    countDunkel++;
  }
  if (props.liebesbuechse === true) {
    countLiebe++;
  }

  // erstellt vs. angepasst
  const createdStr = attrs.created;
  const updatedStr = attrs.updated;

  if (createdStr && updatedStr) {
    const created = new Date(createdStr);
    const updated = new Date(updatedStr);

    if (!Number.isNaN(created.getTime()) && !Number.isNaN(updated.getTime())) {
      if (created.getTime() === updated.getTime()) {
        // Profil in diesem Zustand angelegt (created == updated)
        createdProfiles++;
      } else {
        // Profil wurde irgendwann nach Erstellung geändert
        updatedProfiles++;
      }
    } else {
      profilesWithoutTimestamps++;
    }
  } else {
    profilesWithoutTimestamps++;
  }
}

// Function-Node muss ein Array von Items zurückgeben
return [
  {
    json: {
      totalItems: items.length,
      zauberbuechse_true: countZauber,
      dunkelbuechse_true: countDunkel,
      liebesbuechse_true: countLiebe,
      created_profiles: createdProfiles,
      updated_profiles: updatedProfiles,
      profiles_without_valid_timestamps: profilesWithoutTimestamps,
    },
  },
];

